import { URLS } from './constants.js';
export class NmsClient {
    options;
    token = null;
    tokenExpiry = 0;
    environment;
    constructor(options) {
        this.options = options;
        this.environment = options.environment ?? "production";
    }
    async _refreshToken() {
        const body = new URLSearchParams({
            grant_type: "client_credentials"
        });
        const response = await fetch(URLS[this.environment].auth, {
            method: "POST",
            headers: {
                "Content-Type": "application/x-www-form-urlencoded",
                "Authorization": "Basic " +
                    Buffer.from(`${this.options.clientId}:${this.options.clientSecret}`).toString("base64")
            },
            body: body.toString()
        });
        if (!response.ok) {
            const errText = await response.text();
            throw new Error(`Token request failed: ${response.status} - ${errText}`);
        }
        const data = await response.json();
        this.token = data.access_token;
        this.tokenExpiry = Date.now() + (data.expires_in - 60) * 1000;
    }
    async _getToken() {
        if (!this.token || Date.now() >= this.tokenExpiry) {
            await this._refreshToken();
        }
        return this.token;
    }
    /**
     * Helper to make API requests with automatic token insertion
     */
    async _request(endpoint, options, customHeaders, returnAs = 'json') {
        const token = await this._getToken();
        const url = new URL(`${URLS[this.environment].api}${endpoint.startsWith('/') ? endpoint : `/${endpoint}`}`);
        const headers = new Headers(options?.headers || {});
        headers.set("Authorization", `Bearer ${token}`);
        if (!headers.has("Accept")) {
            headers.set("Accept", "application/json");
        }
        if (customHeaders) {
            for (const [key, value] of Object.entries(customHeaders)) {
                headers.set(key, value);
            }
        }
        const response = await fetch(url.toString(), {
            ...options,
            headers
        });
        if (!response.ok && response.status !== 307) {
            const errText = await response.text();
            throw new Error(`NMS API request failed: ${response.status} ${response.statusText} - ${errText}`);
        }
        if (returnAs === 'response') {
            return response;
        }
        if (response.status === 307) {
            // Can be returned for relative URLs (allowRedirect false)
            return response.json();
        }
        return response.json();
    }
    _buildQueryString(params) {
        const queryParams = new URLSearchParams();
        for (const [key, value] of Object.entries(params)) {
            if (value !== undefined) {
                queryParams.append(key, String(value));
            }
        }
        const str = queryParams.toString();
        return str ? `?${str}` : "";
    }
    // --- Endpoints --- //
    /**
     * Proxies access to binary data to support a streamed data response.
     */
    async getContent(token) {
        return this._request(`/v1/content/${encodeURIComponent(token)}`, undefined, undefined, 'response');
    }
    /**
     * Returns a set of Location-Series data.
     */
    async getLocationSeries(params) {
        return this._request(`/v1/locationseries${this._buildQueryString(params || {})}`);
    }
    /**
     * Returns a partial set of NOTAM data based on the provided query parameters.
     */
    async getFilteredNotams(nmsResponseFormat, params) {
        return this._request(`/v1/notams${this._buildQueryString(params || {})}`, undefined, { nmsResponseFormat });
    }
    /**
     * Returns checklist formatted subset of NOTAM data based on the provided query parameters.
     */
    async getNotamsChecklist(params) {
        return this._request(`/v1/notams/checklist${this._buildQueryString(params || {})}`);
    }
    /**
     * Returns either a binary file or relative content path referencing a compressed initial load file.
     */
    async getInitialLoad(params) {
        // If allowRedirect is implicitly or explicitly true, fetch might follow it automatically
        // Returning as Response allows handling binary stream.
        return this._request(`/v1/notams/il${this._buildQueryString(params || {})}`, undefined, undefined, 'json'); // Fallback json as per 307
    }
    /**
     * Returns either a binary file or relative content path referencing a compressed initial load file by classification.
     */
    async getInitialLoadByClassification(classification, params) {
        return this._request(`/v1/notams/il/${encodeURIComponent(classification)}${this._buildQueryString(params || {})}`);
    }
}
